window.CODE = Object.assign(window.CODE || {}, {"ch08/function_calling.py":"\"\"\"Function calling with both providers: one round trip, parallel calls and forced routing.\n\n  answer(question)  The model may ask for tools. We run them (in parallel if it asks for several),\n                    send the results back, and get the final answer. One round only; Chapter 9\n                    turns this into a loop.\n  route(message)    Force the model to call route_message, so we always get structured routing data.\n\nRun:  python function_calling.py           (PROVIDER from .env)\n\"\"\"\nimport json\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nimport llm  # noqa: E402\n\nfrom tools import RouteArgs, run_tool, specs  # noqa: E402\n\nSYSTEM = (\"You are the City Clinic helpdesk. Use the tools for schedules and fees; never guess. \"\n          \"No medical advice.\")\nANSWER_TOOLS = [\"get_doctor_schedule\", \"opd_fee\"]\n\n\ndef answer(question: str, provider: str | None = None) -> dict:\n    provider = provider or llm.PROVIDER\n    client, model = llm._client(provider), llm.MODELS[provider]\n    if provider == \"openai\":\n        messages = [{\"role\": \"system\", \"content\": SYSTEM}, {\"role\": \"user\", \"content\": question}]\n        r = client.chat.completions.create(model=model, messages=messages, tools=specs(\"openai\", ANSWER_TOOLS),\n                                           tool_choice=\"auto\")\n        msg = r.choices[0].message\n        if not msg.tool_calls:                                   # answered without tools\n            return {\"answer\": msg.content, \"calls\": []}\n        messages.append(msg)\n        calls = []\n        for c in msg.tool_calls:                                 # the model may ask for several at once\n            result = run_tool(c.function.name, c.function.arguments)\n            calls.append({\"tool\": c.function.name, \"args\": c.function.arguments, \"result\": result})\n            messages.append({\"role\": \"tool\", \"tool_call_id\": c.id, \"content\": json.dumps(result)})\n        final = client.chat.completions.create(model=model, messages=messages, tools=specs(\"openai\", ANSWER_TOOLS))\n        return {\"answer\": final.choices[0].message.content, \"calls\": calls}\n\n    messages = [{\"role\": \"user\", \"content\": question}]\n    r = client.messages.create(model=model, max_tokens=800, system=SYSTEM, messages=messages,\n                               tools=specs(\"anthropic\", ANSWER_TOOLS), tool_choice={\"type\": \"auto\"})\n    if r.stop_reason != \"tool_use\":\n        return {\"answer\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"calls\": []}\n    messages.append({\"role\": \"assistant\", \"content\": r.content})\n    calls, results = [], []\n    for b in r.content:\n        if b.type == \"tool_use\":\n            result = run_tool(b.name, b.input)\n            calls.append({\"tool\": b.name, \"args\": b.input, \"result\": result})\n            results.append({\"type\": \"tool_result\", \"tool_use_id\": b.id, \"content\": json.dumps(result)})\n    messages.append({\"role\": \"user\", \"content\": results})       # all results in ONE user message\n    final = client.messages.create(model=model, max_tokens=800, system=SYSTEM, messages=messages,\n                                   tools=specs(\"anthropic\", ANSWER_TOOLS))\n    return {\"answer\": \"\".join(b.text for b in final.content if b.type == \"text\"), \"calls\": calls}\n\n\ndef route(message: str, provider: str | None = None) -> RouteArgs:\n    \"\"\"Forced tool choice: the model MUST call route_message, so the output is always structured.\"\"\"\n    provider = provider or llm.PROVIDER\n    client, model = llm._client(provider), llm.MODELS[provider]\n    if provider == \"openai\":\n        r = client.chat.completions.create(\n            model=model, messages=[{\"role\": \"user\", \"content\": message}], tools=specs(\"openai\", [\"route_message\"]),\n            tool_choice={\"type\": \"function\", \"function\": {\"name\": \"route_message\"}})\n        raw = r.choices[0].message.tool_calls[0].function.arguments\n    else:\n        r = client.messages.create(\n            model=model, max_tokens=300, messages=[{\"role\": \"user\", \"content\": message}],\n            tools=specs(\"anthropic\", [\"route_message\"]), tool_choice={\"type\": \"tool\", \"name\": \"route_message\"})\n        raw = next(b.input for b in r.content if b.type == \"tool_use\")\n    return RouteArgs.model_validate_json(raw) if isinstance(raw, str) else RouteArgs.model_validate(raw)\n\n\nif __name__ == \"__main__\":\n    r = answer(\"Is Dr Iyer in on Thursday, and what will a follow-up 5 days after my last visit cost?\")\n    for c in r[\"calls\"]:\n        print(f\"  tool: {c['tool']}({c['args']}) -> {c['result']}\")\n    print(r[\"answer\"])\n    for m in [\"My bill shows two consultation charges\", \"my mother is very breathless since an hour\"]:\n        print(route(m))\n","ch08/test_tools.py":"\"\"\"Unit tests for the tools. Tools are ordinary code, so test them like ordinary code:\nno model, no key, milliseconds to run.\n\nRun:  pytest -q test_tools.py\n\"\"\"\nfrom tools import REGISTRY, run_tool, specs\n\n\ndef test_schedule_valid():\n    r = run_tool(\"get_doctor_schedule\", {\"department\": \"cardiology\"})\n    assert r[\"doctors\"][\"Dr Rao\"] == [\"Thu\", \"Fri\"]\n\n\ndef test_schedule_rejects_unknown_department():\n    r = run_tool(\"get_doctor_schedule\", {\"department\": \"neurology\"})\n    assert \"error\" in r and \"department\" in r[\"error\"]\n\n\ndef test_arguments_as_json_string():        # OpenAI sends arguments as a JSON string\n    assert run_tool(\"opd_fee\", '{\"visit_type\": \"new\"}')[\"fee_rs\"] == 100\n\n\ndef test_follow_up_rules():\n    assert run_tool(\"opd_fee\", {\"visit_type\": \"follow_up\", \"days_since_last_visit\": 5})[\"fee_rs\"] == 0\n    assert run_tool(\"opd_fee\", {\"visit_type\": \"follow_up\", \"days_since_last_visit\": 9})[\"fee_rs\"] == 100\n\n\ndef test_negative_days_rejected():\n    assert \"error\" in run_tool(\"opd_fee\", {\"visit_type\": \"follow_up\", \"days_since_last_visit\": -2})\n\n\ndef test_bad_json_and_unknown_tool():\n    assert \"not valid JSON\" in run_tool(\"opd_fee\", \"{visit_type: new\")[\"error\"]\n    assert \"Unknown tool\" in run_tool(\"delete_records\", {})[\"error\"]\n\n\ndef test_specs_for_both_providers():\n    o, a = specs(\"openai\"), specs(\"anthropic\")\n    assert len(o) == len(a) == len(REGISTRY)\n    assert o[0][\"function\"][\"parameters\"][\"required\"] == [\"department\"]\n    assert a[0][\"input_schema\"][\"properties\"][\"department\"][\"enum\"] == [\"cardiology\", \"orthopaedics\", \"paediatrics\"]\n","ch08/tools.py":"\"\"\"Typed tools: define each tool once with Pydantic; get its schema, validation and both\nproviders' formats for free.\n\n    @tool(ScheduleArgs)\n    def get_doctor_schedule(args): ...\n\nThe model only ever sees the name, the docstring and the JSON Schema generated from the\nPydantic model. Your code validates the arguments before anything runs.\n\"\"\"\nimport json\nfrom typing import Callable, Literal\n\nfrom pydantic import BaseModel, Field, ValidationError\n\nREGISTRY: dict[str, dict] = {}\n\n\ndef tool(args_model: type[BaseModel]):\n    \"\"\"Decorator: register a function as a tool whose arguments are described by args_model.\"\"\"\n    def register(fn: Callable) -> Callable:\n        REGISTRY[fn.__name__] = {\"fn\": fn, \"args\": args_model, \"description\": \" \".join((fn.__doc__ or \"\").split())}\n        return fn\n    return register\n\n\n# ------------------------------------------------------------------ the tools\nSCHEDULE = {\"cardiology\": {\"Dr Mehta\": [\"Mon\", \"Wed\"], \"Dr Rao\": [\"Thu\", \"Fri\"]},\n            \"orthopaedics\": {\"Dr Iyer\": [\"Tue\", \"Thu\"]},\n            \"paediatrics\": {\"Dr Khan\": [\"Mon\", \"Tue\", \"Fri\"]}}\n\n\nclass ScheduleArgs(BaseModel):\n    department: Literal[\"cardiology\", \"orthopaedics\", \"paediatrics\"] = Field(\n        description=\"Hospital department. Heart = cardiology, bones/joints = orthopaedics, children = paediatrics.\")\n\n\n@tool(ScheduleArgs)\ndef get_doctor_schedule(args: ScheduleArgs) -> dict:\n    \"\"\"Which doctors in a department see OPD patients on which weekdays.\n    Use before answering any question about a doctor's availability.\"\"\"\n    return {\"department\": args.department, \"doctors\": SCHEDULE[args.department]}\n\n\nclass FeeArgs(BaseModel):\n    visit_type: Literal[\"new\", \"follow_up\"] = Field(description=\"'new' for a first visit, 'follow_up' for a repeat visit\")\n    days_since_last_visit: int | None = Field(None, ge=0, description=\"Only for follow-ups: days since the last visit\")\n\n\n@tool(FeeArgs)\ndef opd_fee(args: FeeArgs) -> dict:\n    \"\"\"Calculate the OPD consultation fee in rupees. Use for any question about what a visit costs.\"\"\"\n    if args.visit_type == \"follow_up\" and args.days_since_last_visit is not None and args.days_since_last_visit <= 7:\n        return {\"fee_rs\": 0, \"reason\": \"Follow-up within 7 days with the same doctor is free.\"}\n    return {\"fee_rs\": 100, \"reason\": \"Standard OPD registration fee, valid 7 days for the same doctor.\"}\n\n\nclass RouteArgs(BaseModel):\n    category: Literal[\"appointment\", \"billing\", \"complaint\", \"emergency\", \"other\"]\n    urgent: bool = Field(description=\"True for any symptom that could be an emergency\")\n    summary: str = Field(max_length=120, description=\"One short sentence summarising the request\")\n\n\ndef route_message(args: RouteArgs) -> dict:\n    \"\"\"Record how a helpdesk message should be routed.\"\"\"\n    return args.model_dump()\n\n\nREGISTRY[\"route_message\"] = {\"fn\": route_message, \"args\": RouteArgs,\n                             \"description\": \"Record the category and urgency of a helpdesk message so it reaches the right team.\"}\n\n\n# ------------------------------------------------------------------ formats for each provider\ndef specs(provider: str, names: list[str] | None = None) -> list[dict]:\n    out = []\n    for name, t in REGISTRY.items():\n        if names and name not in names:\n            continue\n        schema = t[\"args\"].model_json_schema()\n        if provider == \"openai\":\n            out.append({\"type\": \"function\", \"function\": {\"name\": name, \"description\": t[\"description\"], \"parameters\": schema}})\n        else:\n            out.append({\"name\": name, \"description\": t[\"description\"], \"input_schema\": schema})\n    return out\n\n\n# ------------------------------------------------------------------ safe execution\ndef run_tool(name: str, raw_args: dict | str) -> dict:\n    \"\"\"Validate the model's arguments, then run the tool. Problems come back as error messages\n    the model can read and fix, never as crashes.\"\"\"\n    t = REGISTRY.get(name)\n    if t is None:\n        return {\"error\": f\"Unknown tool '{name}'. Available: {list(REGISTRY)}\"}\n    try:\n        data = json.loads(raw_args) if isinstance(raw_args, str) else raw_args\n        args = t[\"args\"].model_validate(data)\n    except json.JSONDecodeError:\n        return {\"error\": \"Arguments were not valid JSON.\"}\n    except ValidationError as err:\n        problems = \"; \".join(f\"{'.'.join(map(str, e['loc'])) or 'arguments'}: {e['msg']}\" for e in err.errors())\n        return {\"error\": f\"Invalid arguments: {problems}\"}\n    try:\n        return t[\"fn\"](args)\n    except Exception as exc:\n        return {\"error\": f\"{type(exc).__name__}: {exc}\"}\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
